export interface Room {
  description: string;
  exits: { name: string; toRoom: number }[];
  takeableItems?: string[];
}

export class GameState {
  private state: { rooms: Room[]; current: number; inventory: string[] };
  constructor(rooms: Room[]) {
    this.state = { rooms, current: 0, inventory: [] };
  }
  get currentRoom() { return this.state.rooms[this.state.current]; }
  processCommand(command: string): string {
    const words = command.split(' ');
    if (words.length < 1) return 'What is it?';
    const firstWord = words[0];
    switch (firstWord) {
      case 'look':
      case 'examine':
        return this.currentRoom.description;
      case 'go':
        if (words.length < 2) return 'Where are you trying to go?';
        const dir = words[1];
        const exits = this.currentRoom.exits.find((e) => e.name.toLowerCase() === dir.toLowerCase());
        if (exits) return `You go to the ${exits.name} and find ${this.state.rooms[exits.toRoom].description}`;
        return 'There is no way out that way.';
      case 'take':
        if (words.length < 2) return 'Take what?';
        const item = words[1];
        const takeableItems = this.currentRoom.takeableItems ?? [];
        if (takeableItems.includes(item)) {
          this.state.inventory.push(item);
          return `You take the ${item}.`;
        }
        return 'There is nothing to take here.';
      default:
        return 'I don’t know how to do that.';
    }
  }
}
