const AXIS = ['x', 'y', 'z'];
const queue = [];
let busy = false;
function rotateLayer(axis, layer, dir, speedMs = 260) {
  queue.push({ axis, layer, dir, speedMs });
  pump();
}
function pump() {
  if (busy || queue.length === 0) return;
  busy = true;
  const { axis, layer, dir, speedMs } = queue.shift();
  const pivot = new THREE.Group();
  scene.add(pivot);
  const members = cubies.filter(c => Math.round(c.mesh.position[AXIS[axis]]) === layer);
  members.forEach(c => pivot.attach(c.mesh));
  const target = dir * Math.PI / 2;
  const t0 = performance.now();
  function step(now) {
    const k = Math.min(1, (now - t0) / speedMs);
    const ease = k < 0.5 ? 2 * k * k : 1 - Math.pow(-2 * k + 2, 2) / 2;
    pivot.rotation[AXIS[axis]] = target * ease;
    if (k < 1) { requestAnimationFrame(step); return; }
    members.forEach(c => scene.attach(c.mesh));
    scene.remove(pivot);
    busy = false;
    pump();
  }
  requestAnimationFrame(step);
}

